import fs from 'fs';
import path from 'path';

const pdfjs = await import('pdfjs-dist/legacy/build/pdf.mjs');

const files = process.argv.slice(2);

for (const file of files) {
  console.log('\n========== ' + path.basename(file) + ' ==========');
  const data = new Uint8Array(fs.readFileSync(file));
  const doc = await pdfjs.getDocument({ data, useSystemFonts: true }).promise;
  console.log('pages:', doc.numPages);
  const meta = await doc.getMetadata();
  console.log('meta:', JSON.stringify(meta.info && { Title: meta.info.Title, Author: meta.info.Author, Producer: meta.info.Producer, CreationDate: meta.info.CreationDate }));
  for (let p = 1; p <= Math.min(doc.numPages, 3); p++) {
    const page = await doc.getPage(p);
    const tc = await page.getTextContent();
    console.log(`--- page ${p} items: ${tc.items.length} ---`);
    // group items by y
    const rows = new Map();
    for (const it of tc.items) {
      if (!it.str) continue;
      const y = Math.round(it.transform[5]);
      if (!rows.has(y)) rows.set(y, []);
      rows.get(y).push({ x: Math.round(it.transform[4]), s: it.str });
    }
    const sorted = [...rows.entries()].sort((a, b) => b[0] - a[0]);
    for (const [y, items] of sorted) {
      items.sort((a, b) => b.x - a.x); // RTL: right to left
      console.log(`y=${y}: ` + items.map(i => i.s).join(' | '));
    }
  }
  await doc.destroy();
}

import fs from 'fs';
const pdfjs = await import('pdfjs-dist/legacy/build/pdf.mjs');
const file = process.argv[2];
const data = new Uint8Array(fs.readFileSync(file));
const doc = await pdfjs.getDocument({ data }).promise;
const page = await doc.getPage(1);
const tc = await page.getTextContent();
const seen = new Map();
for (const it of tc.items) {
  if (!it.fontName) continue;
  if (!seen.has(it.fontName)) seen.set(it.fontName, { items: 0, sample: [] });
  const e = seen.get(it.fontName);
  e.items++;
  if (e.sample.length < 3 && it.str) e.sample.push(it.str);
}
for (const [name, info] of seen) {
  const common = await page.commonObjs.get(name);
  console.log('\nFONT:', name, 'items=', info.items);
  console.log('  type:', common.type, 'subtype:', common.subtype, 'baseFont:', common.baseFont);
  console.log('  encoding:', JSON.stringify(common.encoding));
  console.log('  ToUnicode present:', !!common.toUnicode);
  console.log('  sample items:', JSON.stringify(info.sample));
  if (common.toUnicode) {
    const t = await common.toUnicode;
    const s = typeof t === 'string' ? t : (t.str || JSON.stringify(t));
    console.log('  ToUnicode (first 600):', String(s).slice(0, 600));
  }
  if (common.data) {
    console.log('  data keys:', Object.keys(common.data));
    console.log('  data.encoding:', JSON.stringify(common.data.encoding));
    if (common.data.toUnicode) {
      const t = typeof common.data.toUnicode === 'string' ? common.data.toUnicode : JSON.stringify(common.data.toUnicode);
      console.log('  data.toUnicode first 800:', String(t).slice(0, 800));
    }
  }
}

import fs from 'fs';
const pdfjs = await import('pdfjs-dist/legacy/build/pdf.mjs');
const file = process.argv[2];
const data = new Uint8Array(fs.readFileSync(file));
const doc = await pdfjs.getDocument({ data, standardFontDataUrl: undefined }).promise;
const page = await doc.getPage(1);
await page.getOperatorList();
const tc = await page.getTextContent();
const seen = new Map();
for (const it of tc.items) {
  if (!it.fontName) continue;
  if (!seen.has(it.fontName)) seen.set(it.fontName, { items: 0, sample: [] });
  const e = seen.get(it.fontName);
  e.items++;
  if (e.sample.length < 4 && it.str) e.sample.push(it.str);
}
for (const [name, info] of seen) {
  let common;
  try { common = await page.commonObjs.get(name); } catch (e) { console.log('FONT', name, 'ERR', e.message); continue; }
  console.log('\nFONT:', name, 'items=', info.items);
  console.log('  baseFont:', common.baseFont, 'subtype:', common.subtype, 'type:', common.type);
  console.log('  encoding:', JSON.stringify(common.encoding));
  const tu = common.toUnicode;
  console.log('  toUnicode type:', tu && typeof tu);
  if (tu) {
    let s;
    try { s = (typeof tu === 'string') ? tu : (tu.str ?? JSON.stringify(tu)); } catch {}
    try { if (tu instanceof Object && typeof tu.get === 'function') s = tu.toString(); } catch {}
    console.log('  ToUnicode:', String(s).slice(0, 1500));
  }
  console.log('  sample:', JSON.stringify(info.sample));
}

import fs from 'fs';
import zlib from 'zlib';

const file = process.argv[2];
const buf = fs.readFileSync(file);
const latin = buf.toString('latin1');

// find all stream objects, try to inflate, detect TrueType
const re = /(\d+)\s+0\s+obj([\s\S]*?)endobj/g;
let m;
let idx = 0;
while ((m = re.exec(latin))) {
  const objNum = m[1];
  const dict = m[2];
  const sm = dict.match(/stream\r?\n/);
  if (!sm) continue;
  const start = m.index + sm.index + sm[0].length;
  const end = latin.indexOf('endstream', start);
  if (end < 0) continue;
  let data = buf.subarray(start, end);
  // trim trailing EOL
  while (data.length && (data[data.length-1] === 0x0a || data[data.length-1] === 0x0d)) data = data.subarray(0, data.length-1);
  let out = null;
  if (/FlateDecode/.test(dict)) { try { out = zlib.inflateSync(data); } catch(e) { continue; } }
  else if (!/Filter/.test(dict)) out = data;
  if (!out) continue;
  if (out.length > 4 && out[0] === 0x00 && out[1] === 0x01 && out[2] === 0x00 && out[3] === 0x00) {
    // TrueType
    console.log(`\n=== obj ${objNum}: TrueType, ${out.length} bytes, dict: ${dict.slice(0,200).replace(/\s+/g,' ')}`);
    parseTTF(out);
  } else if (out.slice(0,4).toString('latin1') === 'OTTO') {
    console.log(`\n=== obj ${objNum}: CFF/OpenType ${out.length}`);
  } else if (out.slice(0,4).toString('latin1') === 'wOFF') {
    console.log(`\n=== obj ${objNum}: wOFF`);
  }
}

function parseTTF(ttf) {
  const numTables = ttf.readUInt16BE(4);
  const tables = {};
  for (let i = 0; i < numTables; i++) {
    const o = 12 + i * 16;
    const tag = ttf.subarray(o, o+4).toString('latin1');
    const off = ttf.readUInt32BE(o+8);
    const len = ttf.readUInt32BE(o+12);
    tables[tag] = { off, len };
  }
  console.log('  tables:', Object.keys(tables).join(','));
  if (tables.name) {
    try {
      const t = tables.name;
      const count = ttf.readUInt16BE(t.off+2);
      const strOff = t.off + ttf.readUInt16BE(t.off+4);
      const names = [];
      for (let i = 0; i < count; i++) {
        const o = t.off + 6 + i*12;
        const pid = ttf.readUInt16BE(o), eid = ttf.readUInt16BE(o+2), lid = ttf.readUInt16BE(o+4);
        const nid = ttf.readUInt16BE(o+6), len2 = ttf.readUInt16BE(o+8), off2 = ttf.readUInt16BE(o+10);
        if (nid <= 6) {
          let s = ttf.subarray(strOff+off2, strOff+off2+len2);
          let txt = (pid === 3 || pid === 0) ? s.toString('utf16le').replace(/..?/, '') : s.toString('latin1');
          if (pid === 3) { // utf16be
            const b = Buffer.from(s); txt = b.swap16().toString('utf16le');
          } else txt = s.toString('latin1');
          names.push(`${nid}=${txt}`);
        }
      }
      console.log('  name:', [...new Set(names)].join(' | '));
    } catch(e) { console.log('  name parse err', e.message); }
  }
  if (tables.cmap) {
    const t = tables.cmap;
    const n = ttf.readUInt16BE(t.off+2);
    console.log('  cmap subtables:', n);
    for (let i = 0; i < n; i++) {
      const o = t.off + 4 + i*8;
      const pid = ttf.readUInt16BE(o), eid = ttf.readUInt16BE(o+10-8+0);
      const off = ttf.readUInt32BE(o+4);
      const fmt = ttf.readUInt16BE(t.off + off);
      console.log(`    platform=${pid} encoding=${ttf.readUInt16BE(o+2)} format=${fmt} offset=${off}`);
      if (fmt === 4) parseFmt4(ttf, t.off + off, pid, ttf.readUInt16BE(o+2));
      if (fmt === 12) parseFmt12(ttf, t.off + off);
      if (fmt === 6) parseFmt6(ttf, t.off + off);
      if (fmt === 0) parseFmt0(ttf, t.off + off);
    }
  }
}
function parseFmt4(t, off, pid, eid) {
  const segCountX2 = t.readUInt16BE(off+6);
  const segCount = segCountX2/2;
  const endOff = off+14;
  const startOff = endOff + segCountX2 + 2;
  const deltaOff = startOff + segCountX2;
  const rangeOff = deltaOff + segCountX2;
  let mapped = 0, sample = [];
  for (let s = 0; s < segCount; s++) {
    const end = t.readUInt16BE(endOff + s*2);
    const start = t.readUInt16BE(startOff + s*2);
    const delta = t.readInt16BE(deltaOff + s*2);
    const ro = t.readUInt16BE(rangeOff + s*2);
    if (start === 0xFFFF) continue;
    for (let c = start; c <= end && c !== 0x10000; c++) {
      let gid;
      if (ro === 0) gid = (c + delta) & 0xFFFF;
      else {
        const gi = rangeOff + s*2 + ro + (c - start)*2;
        if (gi + 1 >= t.length) continue;
        gid = t.readUInt16BE(gi);
        if (gid !== 0) gid = (gid + delta) & 0xFFFF;
      }
      if (gid !== 0) { mapped++; if (sample.length < 8) sample.push(`U+${c.toString(16)}->gid${gid}`); }
    }
  }
  console.log(`      fmt4 pid=${pid} eid=${eid}: mapped=${mapped} sample=${sample.join(', ')}`);
}
function parseFmt12(t, off) {
  const nGroups = t.readUInt32BE(off+12);
  let mapped = 0, sample = [];
  for (let i = 0; i < Math.min(nGroups, 100000); i++) {
    const o = off + 16 + i*12;
    const sc = t.readUInt32BE(o), ec = t.readUInt32BE(o+4), sg = t.readUInt32BE(o+8);
    for (let c = sc; c <= ec && c - sc < 50; c++) { mapped++; if (sample.length < 6) sample.push(`U+${c.toString(16)}->gid${sg + (c-sc)}`); }
  }
  console.log(`      fmt12: groups=${nGroups} mapped(sampled)=${mapped} sample=${sample.join(', ')}`);
}
function parseFmt6(t, off) {
  const first = t.readUInt16BE(off+6), count = t.readUInt16BE(off+8);
  const sample = [];
  for (let i = 0; i < Math.min(count, 8); i++) { const gid = t.readUInt16BE(off+10+i*2); sample.push(`U+${(first+i).toString(16)}->gid${gid}`); }
  console.log(`      fmt6: first=U+${first.toString(16)} count=${count} sample=${sample.join(', ')}`);
}
function parseFmt0(t, off) {
  const sample = [];
  for (let i = 0; i < 32; i++) { const gid = t[off+6+i]; if (gid) sample.push(`U+${i.toString(16)}->gid${gid}`); }
  console.log(`      fmt0 sample=${sample.join(', ')}`);
}

import fs from 'fs';
import zlib from 'zlib';

const file = process.argv[2];
const buf = fs.readFileSync(file);
const latin = buf.toString('latin1');

const markers = ['/FontFile2', '/FontFile3', '/FontFile ', '/ToUnicode', '/Subtype /Type0', '/Subtype/Type0', '/Encoding'];
for (const mk of markers) {
  let i = 0, n = 0;
  while ((i = latin.indexOf(mk, i)) !== -1 && n < 3) { n++; i += mk.length; }
  console.log(mk, 'occurrences(first3):', n);
}

// find /FontFile2 references and resolve object numbers
const refs = new Set();
let re = /\/FontFile2\s+(\d+)\s+0\s+R/g, m;
while ((m = re.exec(latin))) refs.add(m[1]);
re = /\/FontFile3\s+(\d+)\s+0\s+R/g;
while ((m = re.exec(latin))) refs.add(m[1]);
re = /\/ToUnicode\s+(\d+)\s+0\s+R/g;
while ((m = re.exec(latin))) refs.add(m[1]);
console.log('refs:', [...refs].join(','));

function findObj(num) {
  const pat = new RegExp('(?:^|[^\\d])' + num + '\\s+0\\s+obj');
  const mm = pat.exec(latin);
  if (!mm) return null;
  const start = mm.index + mm[0].length;
  const dictEnd = latin.indexOf('stream', start);
  const objEnd = latin.indexOf('endobj', start);
  const limit = dictEnd !== -1 && dictEnd < objEnd ? dictEnd : objEnd;
  const dict = latin.slice(start, limit);
  let data = null;
  if (dictEnd !== -1 && (objEnd === -1 || dictEnd < objEnd)) {
    let s = dictEnd;
    if (latin[s+6] === '\r') s += 7; else if (latin[s+6] === '\n') s += 7; else s += 6;
    const e = latin.indexOf('endstream', s);
    data = buf.subarray(s, e);
    while (data.length && (data[data.length-1]===10 || data[data.length-1]===13)) data = data.subarray(0, data.length-1);
    if (/FlateDecode/.test(dict)) { try { data = zlib.inflateSync(data); } catch(err) { data = null; } }
  }
  return { dict, data };
}

for (const num of refs) {
  const o = findObj(num);
  if (!o) { console.log(`obj ${num}: NOT FOUND`); continue; }
  console.log(`\nobj ${num}: dict=${o.dict.replace(/\s+/g,' ').slice(0,300)}`);
  if (o.data) {
    const head = o.data.subarray(0, 4).toString('latin1');
    console.log(`  data ${o.data.length} bytes head=${JSON.stringify(head)}`);
    if (o.data[0]===0 && o.data[1]===1 && o.data[2]===0 && o.data[3]===0) {
      // TrueType
      const ttf = o.data;
      const numTables = ttf.readUInt16BE(4);
      const tags = [];
      for (let i=0;i<numTables;i++) tags.push(ttf.subarray(12+i*16, 16+i*16).toString('latin1'));
      console.log('  tables:', tags.join(','));
      // name
      const ti = tags.indexOf('name');
      if (ti>=0) {
        const t = { off: ttf.readUInt32BE(12+ti*16+8), len: ttf.readUInt32BE(12+ti*16+12) };
        const count = ttf.readUInt16BE(t.off+2), strOff = t.off + ttf.readUInt16BE(t.off+4);
        const names = [];
        for (let i=0;i<count;i++) {
          const o2 = t.off+6+i*12;
          const pid=ttf.readUInt16BE(o2), nid=ttf.readUInt16BE(o2+6), len2=ttf.readUInt16BE(o2+8), off2=ttf.readUInt16BE(o2+10);
          if (nid<=6 && nid>=1) {
            const s = ttf.subarray(strOff+off2, strOff+off2+len2);
            let txt = (pid===3)? Buffer.from(s).swap16().toString('utf16le') : s.toString('latin1');
            names.push(`${nid}:${txt}`);
          }
        }
        console.log('  name:', [...new Set(names)].join(' | '));
      }
      const ci = tags.indexOf('cmap');
      if (ci>=0) {
        const off = ttf.readUInt32BE(12+ci*16+8);
        const n = ttf.readUInt16BE(off+2);
        for (let i=0;i<n;i++) {
          const o2 = off+4+i*8;
          const pid = ttf.readUInt16BE(o2), eid = ttf.readUInt16BE(o2+2), sub = ttf.readUInt32BE(o2+4);
          const fmt = ttf.readUInt16BE(off+sub);
          console.log(`  cmap: pid=${pid} eid=${eid} fmt=${fmt}`);
          if (fmt===4) {
            const segX2 = ttf.readUInt16BE(off+sub+6), seg = segX2/2;
            const endO = off+sub+14, startO = endO+segX2+2, deltaO = startO+segX2, roO = deltaO+segX2;
            let cnt=0, samp=[];
            for (let s2=0;s2<seg;s2++){
              const en=ttf.readUInt16BE(endO+s2*2), st=ttf.readUInt16BE(startO+s2*2);
              const dl=ttf.readInt16BE(deltaO+s2*2), ro=ttf.readUInt16BE(roO+s2*2);
              if (st===0xFFFF) continue;
              for(let c=st;c<=en;c++){
                let g;
                if(ro===0) g=(c+dl)&0xFFFF;
                else { const gi=roO+s2*2+ro+(c-st)*2; g=ttf.readUInt16BE(gi); if(g) g=(g+dl)&0xFFFF; }
                if(g){cnt++; if(samp.length<6) samp.push(`U+${c.toString(16)}->${g}`);}
              }
            }
            console.log(`    mapped=${cnt} sample=${samp.join(', ')}`);
          }
        }
      }
    } else if (head === 'OTTO') {
      console.log('  CFF font');
    }
  }
}

import fs from 'fs';
import { PDFDocument, PDFName, PDFDict, PDFStream, PDFRawStream, PDFArray, PDFNumber, PDFString } from 'pdf-lib';
import zlib from 'zlib';

const file = process.argv[2];
const bytes = fs.readFileSync(file);
const doc = await PDFDocument.load(bytes, { updateMetadata: false });
const ctx = doc.context;

const objs = ctx.enumerateIndirectObjects();
console.log('total indirect objects:', objs.length);

function streamData(stream) {
  try {
    const dict = stream.dict;
    const filter = dict.get(PDFName.of('Filter'));
    let contents;
    try { contents = stream.getContents(); } catch { contents = null; }
    if (!contents) return null;
    if (filter && String(filter) === '/FlateDecode') {
      try { return zlib.inflateSync(Buffer.from(contents)); } catch { return null; }
    }
    return Buffer.from(contents);
  } catch (e) { return null; }
}

// 1) Find all ToUnicode streams
for (const [ref, obj] of objs) {
  if (obj instanceof PDFStream) {
    const dict = obj.dict;
    const hasLength1 = dict.get(PDFName.of('Length1'));
    const keys = dict.keys().map(k => k.toString());
    if (!hasLength1 && keys.includes('/Filter') && keys.length <= 4) {
      const data = streamData(obj);
      if (data && (data.toString('latin1').includes('beginbfchar') || data.toString('latin1').includes('beginbfrange'))) {
        console.log(`\n--- ToUnicode stream @ ${ref.toString()} ---`);
        console.log(data.toString('latin1'));
      }
    }
  }
}

// 2) Find Type0 font dicts
console.log('\n=== Type0 / Font dicts ===');
for (const [ref, obj] of objs) {
  if (obj instanceof PDFDict) {
    const subtype = obj.get(PDFName.of('Subtype'));
    const baseFont = obj.get(PDFName.of('BaseFont'));
    if (!subtype) continue;
    const st = String(subtype);
    if (st.includes('Type0') || st.includes('Type1') || st.includes('TrueType') || st.includes('CIDFont')) {
      const tu = obj.get(PDFName.of('ToUnicode'));
      const enc = obj.get(PDFName.of('Encoding'));
      const desc = obj.get(PDFName.of('FontDescriptor'));
      console.log(`${ref.toString()}: Subtype=${st} BaseFont=${baseFont?String(baseFont):'-'} ToUnicode=${tu?String(tu):'-'} Encoding=${enc?String(enc):'-'}`);
    }
  }
}

