import fs from 'fs';
import zlib from 'zlib';

const buf = fs.readFileSync(process.argv[2]);
const latin = buf.toString('latin1');

// Locate objects 14,16,18 (FontFile2) by scanning for "N 0 obj" outside streams is hard;
// instead find all "/FontFile2 N 0 R" then parse that object by regex allowing \r\n.
const refs = new Set();
let re = /\/FontFile2\s+(\d+)\s+0\s+R/g, m;
while ((m = re.exec(latin))) refs.add(m[1]);

for (const num of refs) {
  const pat = new RegExp('(?:^|[^0-9])' + num + '\\s+0\\s+obj\\s*<<');
  const mm = pat.exec(latin);
  if (!mm) { console.log(num, 'not found'); continue; }
  const start = mm.index + mm[0].length - 2;
  const sKey = latin.indexOf('stream', start);
  const dict = latin.slice(start, sKey);
  let s = sKey + 6;
