      if (ro === 0) g = (c + dl) & 0xFFFF;
      else { const gi = roO + s * 2 + ro + (c - st) * 2; if (gi + 1 >= ttf.length) continue; g = ttf.readUInt16BE(gi); if (g) g = (g + dl) & 0xFFFF; }
