function fontFiles() {
  const refs = new Set();
  let re = /\/FontFile2\s+(\d+)\s+0\s+R/g, m;
  while ((m = re.exec(latin))) refs.add(m[1]);
  const out = [];
  for (const num of refs) {
    const pat = new RegExp('(?:^|[^0-9])' + num + '\\s+0\\s+obj\\s*<<');
    const mm = pat.exec(latin); if (!mm) continue;
    const start = mm.index + mm[0].length - 2;
    const sKey = latin.indexOf('stream', start);
    let s = sKey + 6;
    if (latin[s] === '\r' && latin[s+1] === '\n') s += 2; else if (latin[s] === '\n' || latin[s] === '\r') s += 1;
    const e = latin.indexOf('endstream', s);
    let data = buf.subarray(s, e);
    while (data.length && (data[data.length-1]===10||data[data.length-1]===13)) data = data.subarray(0, data.length-1);
    try { data = zlib.inflateSync(data); } catch { continue; }
    if (data[0]===0 && data[1]===1) out.push({ num, data });
  }
  return out;
}

function cmapEntries(ttf) {
  const n = ttf.readUInt16BE(4); const T = {};
  for (let i=0;i<n;i++){const o=12+i*16;T[ttf.subarray(o,o+4).toString('latin1')]={off:ttf.readUInt32BE(o+8),len:ttf.readUInt32BE(o+12)};}
  const fwd = new Map(); const rev = new Map();
  if (!T.cmap) return { fwd, rev };
  const off=T.cmap.off, cnt=ttf.readUInt16BE(off+2);
  for (let i=0;i<cnt;i++){
    const o=off+4+i*8, pid=ttf.readUInt16BE(o), eid=ttf.readUInt16BE(o+2), sub=ttf.readUInt32BE(o+4);
    const fmt=ttf.readUInt16BE(off+sub);
    if(fmt!==4) continue;
    if (!(pid===3&&eid===1)) continue;
    const t=off+sub, segX2=ttf.readUInt16BE(t+6), seg=segX2/2;
    const endO=t+14,startO=endO+segX2+2,deltaO=startO+segX2,roO=deltaO+segX2;
    for(let sg=0;sg<seg;sg++){
      const en=ttf.readUInt16BE(endO+sg*2),st=ttf.readUInt16BE(startO+sg*2);
      const dl=ttf.readInt16BE(deltaO+sg*2),ro=ttf.readUInt16BE(roO+sg*2);
