// Which fonts used where: parse content stream and collect CIDs per font
function inflateObjStream(num) {
  const pat = new RegExp('(?:^|[^0-9])' + num + '\\s+0\\s+obj\\s*<<');
  const mm = pat.exec(latin); if (!mm) return null;
  const start = mm.index + mm[0].length - 2;
  const sKey = latin.indexOf('stream', start); if (sKey < 0) return null;
  let s = sKey + 6;
  if (latin[s]==='\r'&&latin[s+1]==='\n') s+=2; else if (latin[s]==='\n'||latin[s]==='\r') s+=1;
  const e = latin.indexOf('endstream', s);
  let d = buf.subarray(s, e);
  while (d.length && (d[d.length-1]===10||d[d.length-1]===13)) d = d.subarray(0,d.length-1);
  try { d = zlib.inflateSync(d); } catch {}
  return d;
}

