  const fm = /\/Font\s*<<([^>]*)>>/.exec(latin);
  if (fm) {
    const re2 = /(\/[A-Za-z0-9#+._-]+)\s+(\d+)\s+0\s+R/g; let x;
    while ((x = re2.exec(fm[1]))) fontsRes[x[1]] = x[2];
  }
}
console.log('font resources:', JSON.stringify(fontsRes));

// For each font object, get BaseFont and FontFile2 number
const fontInfo = {};
for (const [name, objNum] of Object.entries(fontsRes)) {
  const pat = new RegExp('(?:^|[^0-9])' + objNum + '\\s+0\\s+obj\\s*<<([^>]*)>>');
  const mm = pat.exec(latin);
  if (!mm) { console.log(name, 'dict not found'); continue; }
  const dict = mm[1];
  const bf = /\/BaseFont\s*\/([^\s/]+)/.exec(dict);
  const df = /\/DescendantFonts\s+(\d+)\s+0\s+R/.exec(dict);
  let ff = null, bf2 = bf ? bf[1] : null;
  if (df) {
    const pat2 = new RegExp('(?:^|[^0-9])' + df[1] + '\\s+0\\s+obj\\s*\\[([^\\]]*)\\]');
    const m2 = pat2.exec(latin);
    if (m2) {
      const cidNum = /(\d+)\s+0\s+R/.exec(m2[1])[1];
      const pat3 = new RegExp('(?:^|[^0-9])' + cidNum + '\\s+0\\s+obj\\s*<<([^>]*)>>');
      const m3 = pat3.exec(latin);
      if (m3) {
        const fd = /\/FontDescriptor\s+(\d+)\s+0\s+R/.exec(m3[1]);
        if (fd) {
          const pat4 = new RegExp('(?:^|[^0-9])' + fd[1] + '\\s+0\\s+obj\\s*<<([^>]*)>>');
          const m4 = pat4.exec(latin);
          if (m4) { const f = /\/FontFile2\s+(\d+)\s+0\s+R/.exec(m4[1]); if (f) ff = f[1]; }
        }
        const bfc = /\/BaseFont\s*\/([^\s/]+)/.exec(m3[1]); if (bfc) bf2 = bfc[1];
      }
    }
  }
