  console.log(name, JSON.stringify(fontInfo[name]));
}

// collect CIDs used per font in content stream
const used = {};
let cur = null;
const re3 = /(\/[A-Za-z0-9#+._-]+)\s+[\d.]+\s+Tf|<([0-9A-Fa-f\s]*)>\s*Tj|\[([^\]]*)\]\s*TJ/g;
let m3;
while ((m3 = re3.exec(content))) {
  if (m3[1]) cur = m3[1];
  else {
    const hex = m3[2] !== undefined ? m3[2] : (m3[3] || '');
    const parts = hex.match(/<([0-9A-Fa-f\s]*)>/g) || (m3[2] !== undefined ? ['<' + hex + '>'] : []);
    if (!used[cur]) used[cur] = new Set();
    for (const p of parts) {
      const h = /^<([0-9A-Fa-f\s]*)>$/.exec(p); if (!h) continue;
      const b = Buffer.from(h[1].replace(/\s+/g, ''), 'hex');
      for (let i = 0; i + 1 < b.length; i += 2) used[cur].add(b.readUInt16BE(i));
    }
  }
