for (const [name, set] of Object.entries(used)) {
  const info = fontInfo[name];
  if (!info || !info.fontFile) { console.log(`\n${name}: no FontFile2 (Type1?), ${set.size} CIDs`); continue; }
  const ff = fontFiles().find(f => f.num === info.fontFile);
  const { rev } = cmapEntries(ff.data);
  const missing = [...set].filter(c => !rev.has(c)).sort((a,b)=>a-b);
  console.log(`\n${name} (${info.baseFont}): used=${set.size} mapped=${set.size - missing.length} missing=${missing.length}`);
  console.log('  missing CIDs:', missing.map(c => '0x' + c.toString(16)).join(' '));
  // show neighbors in cmap for context
  const allGids = [...rev.keys()].sort((a,b)=>a-b);
  for (const g of missing.slice(0, 10)) {
    let before = null, after = null;
    for (const x of allGids) { if (x < g) before = x; if (x > g) { after = x; break; } }
    const fmt = g => g === null ? '-' : `${g}(0x${g.toString(16)}=${String.fromCodePoint(rev.get(g))} U+${rev.get(g).toString(16)})`;
    console.log(`    GID ${g} (0x${g.toString(16)}) prev=${fmt(before)} next=${fmt(after)}`);
  }
}

