import fs from 'fs';
import zlib from 'zlib';

function readTTF(path) { return fs.readFileSync(path); }

function parseCmap(ttf) {
  const n = ttf.readUInt16BE(4); const T = {};
  for (let i=0;i<n;i++){const o=12+i*16;T[ttf.subarray(o,o+4).toString('latin1')]={off:ttf.readUInt32BE(o+8),len:ttf.readUInt32BE(o+12)};}
  const rev = new Map(); const fwd = new Map();
  if (T.cmap) {
    const off=T.cmap.off, cnt=ttf.readUInt16BE(off+2);
    for(let i=0;i<cnt;i++){
      const o=off+4+i*8, sub=ttf.readUInt32BE(o+4), fmt=ttf.readUInt16BE(off+sub);
      if(fmt===4){
        const t=off+sub, segX2=ttf.readUInt16BE(t+6), seg=segX2/2;
        const endO=t+14,startO=endO+segX2+2,deltaO=startO+segX2,roO=deltaO+segX2;
        for(let s=0;s<seg;s++){
          const en=ttf.readUInt16BE(endO+s*2),st=ttf.readUInt16BE(startO+s*2);
          const dl=ttf.readInt16BE(deltaO+s*2),ro=ttf.readUInt16BE(roO+s*2);
          if(st===0xFFFF)continue;
          for(let c=st;c<=en;c++){
            let g; if(ro===0)g=(c+dl)&0xFFFF;
            else{const gi=roO+s*2+ro+(c-st)*2; if(gi+1>=ttf.length)continue; g=ttf.readUInt16BE(gi); if(g)g=(g+dl)&0xFFFF;}
            if(g){ if(!rev.has(g))rev.set(g,c); if(!fwd.has(c))fwd.set(c,g); }
          }
        }
      } else if(fmt===12){
        const t=off+sub, ng=ttf.readUInt32BE(t+12);
        for(let k=0;k<ng;k++){const o2=t+16+k*12;const sc=ttf.readUInt32BE(o2),ec=ttf.readUInt32BE(o2+4),sg=ttf.readUInt32BE(o2+8);
          for(let c=sc;c<=ec;c++){const g=sg+(c-sc); if(!rev.has(g))rev.set(g,c); if(!fwd.has(c))fwd.set(c,g);}}
      } else if(fmt===6){
        const t=off+sub, first=ttf.readUInt16BE(t+6), c3=ttf.readUInt16BE(t+8);
        for(let k=0;k<c3;k++){const g=ttf.readUInt16BE(t+10+k*2); if(g){if(!rev.has(g))rev.set(g,first+k); if(!fwd.has(first+k))fwd.set(first+k,g);}}
      }
    }
  }
  const numGlyphs = T.maxp ? ttf.readUInt16BE(T.maxp.off+4) : 0;
  const head = T.head ? ttf.readUInt32BE(T.head.off+18) : 0; // fontRevision fixed
  return { rev, fwd, numGlyphs, T, fontRevision: T.head ? ttf.readUInt32BE(T.head.off+4) : 0 };
}

function embeddedFont(file, num) {
  const buf = fs.readFileSync(file);
  const latin = buf.toString('latin1');
  const pat = new RegExp('(?:^|[^0-9])' + num + '\\s+0\\s+obj\\s*<<');
  const mm = pat.exec(latin);
  const start = mm.index + mm[0].length - 2;
  const sKey = latin.indexOf('stream', start);
  let s = sKey + 6;
  if (latin[s]==='\r'&&latin[s+1]==='\n') s+=2; else if (latin[s]==='\n'||latin[s]==='\r') s+=1;
  const e = latin.indexOf('endstream', s);
  let d = buf.subarray(s, e);
  while (d.length && (d[d.length-1]===10||d[d.length-1]===13)) d=d.subarray(0,d.length-1);
  return zlib.inflateSync(d);
}

// embedded FontFile2 = obj 18 (Segoe UI), 14 (Arial), 16 (Arial Bold)
const pairs = [
  ['C:\\Users\\cw\\Downloads\\تقرير قوائم الفصول (85).pdf', 18, 'C:\\Windows\\Fonts\\segoeui.ttf', 'Segoe UI'],
  ['C:\\Users\\cw\\Downloads\\تقرير قوائم الفصول (85).pdf', 14, 'C:\\Windows\\Fonts\\arial.ttf', 'Arial'],
  ['C:\\Users\\cw\\Downloads\\تقرير قوائم الفصول (85).pdf', 16, 'C:\\Windows\\Fonts\\arialbd.ttf', 'Arial Bold'],
];
for (const [pdf, num, sysPath, label] of pairs) {
  const emb = embeddedFont(pdf, num);
  const a = parseCmap(emb);
  const b = parseCmap(readTTF(sysPath));
  console.log(`\n${label}: embedded numGlyphs=${a.numGlyphs} cmapEntries=${a.rev.size} | system numGlyphs=${b.numGlyphs} cmapEntries=${b.rev.size}`);
  let mismatch = 0, checked = 0;
  for (const [g, c] of a.rev) {
    checked++;
    const other = b.rev.get(g);
    if (other !== c) { mismatch++; if (mismatch <= 8) console.log(`   MISMATCH GID ${g}: emb=U+${c.toString(16)} sys=${other !== undefined ? 'U+'+other.toString(16) : 'MISSING'}`); }
  }
  console.log(`   checked=${checked} mismatch=${mismatch}`);
  for (const probe of [3941, 3948, 3950, 3971, 3981, 3992]) {
    const c = b.rev.get(probe);
    console.log(`   GID ${probe} => ${c !== undefined ? 'U+' + c.toString(16) + ' ' + String.fromCodePoint(c) : 'MISSING'}`);
