import fs from 'fs';
import { createCanvas } from '@napi-rs/canvas';

const pdfjs = await import('pdfjs-dist/legacy/build/pdf.mjs');

class NodeCanvasFactory {
  create(w, h) {
    const canvas = createCanvas(Math.ceil(w), Math.ceil(h));
    return { canvas, context: canvas.getContext('2d') };
  }
  reset(c, w, h) { c.canvas.width = Math.ceil(w); c.canvas.height = Math.ceil(h); }
  destroy(c) { c.canvas.width = 0; c.canvas.height = 0; }
}

const file = process.argv[2];
const pageNum = parseInt(process.argv[3] || '1', 10);
const out = process.argv[4] || 'page.png';
const scale = parseFloat(process.argv[5] || '2');

const data = new Uint8Array(fs.readFileSync(file));
const doc = await pdfjs.getDocument({ data, canvasFactory: new NodeCanvasFactory() }).promise;
const page = await doc.getPage(pageNum);
const viewport = page.getViewport({ scale });
const canvas = createCanvas(Math.ceil(viewport.width), Math.ceil(viewport.height));
const ctx = canvas.getContext('2d');
ctx.fillStyle = '#fff'; ctx.fillRect(0, 0, canvas.width, canvas.height);
await page.render({ canvasContext: ctx, viewport, canvasFactory: new NodeCanvasFactory() }).promise;
fs.writeFileSync(out, canvas.toBuffer('image/png'));
console.log('wrote', out, canvas.width + 'x' + canvas.height);
await doc.destroy();

