import fs from 'fs';
import { createCanvas } from '@napi-rs/canvas';

const pdfjs = await import('pdfjs-dist/legacy/build/pdf.mjs');
const { execSync } = await import('child_process');

const FONTFILES = {
  '/ABCDEE+Arial': 'C:\\Windows\\Fonts\\arial.ttf',
  '/ABCDEE+Arial,Bold': 'C:\\Windows\\Fonts\\arialbd.ttf',
  '/ABCDEE+Segoe#20UI': 'C:\\Windows\\Fonts\\segoeui.ttf',
};

// minimal TTF glyph reader
const fontCache = new Map();
function loadFont(path) {
  if (fontCache.has(path)) return fontCache.get(path);
  const ttf = fs.readFileSync(path);
  const n = ttf.readUInt16BE(4); const T = {};
  for (let i = 0; i < n; i++) { const o = 12 + i * 16; T[ttf.subarray(o, o + 4).toString('latin1')] = { off: ttf.readUInt32BE(o + 8), len: ttf.readUInt32BE(o + 12) }; }
  const indexToLoc = ttf.readInt16BE(T.head.off + 50);
  const loca = i => indexToLoc === 0 ? ttf.readUInt16BE(T.loca.off + i * 2) * 2 : ttf.readUInt32BE(T.loca.off + i * 4);
  const raw = gid => { const s = loca(gid), e = loca(gid + 1); return e <= s ? null : ttf.subarray(T.glyf.off + s, T.glyf.off + e); };
  const f = { ttf, T, raw, path };
  fontCache.set(path, f);
  return f;
}
function glyphContours(font, gid, depth = 0) {
  const g = font.raw(gid);
  if (!g || g.length < 10 || depth > 4) return [];
  const nc = g.readInt16BE(0);
  if (nc >= 0) {
    const endPts = []; let p = 10;
    for (let i = 0; i < nc; i++) { endPts.push(g.readUInt16BE(p)); p += 2; }
    const insLen = g.readUInt16BE(p); p += 2 + insLen;
    const numPts = endPts[nc - 1] + 1;
    const flags = new Uint8Array(numPts);
    for (let i = 0; i < numPts;) { const fl = g[p++]; flags[i++] = fl; if (fl & 8) { let r = g[p++]; while (r-- > 0 && i < numPts) flags[i++] = fl; } }
    const xs = new Int16Array(numPts); let x = 0;
    for (let i = 0; i < numPts; i++) { const fl = flags[i]; if (fl & 2) { const d = g[p++]; x += (fl & 16) ? d : -d; } else if (!(fl & 16)) { x += g.readInt16BE(p); p += 2; } xs[i] = x; }
    const ys = new Int16Array(numPts); let y = 0;
    for (let i = 0; i < numPts; i++) { const fl = flags[i]; if (fl & 4) { const d = g[p++]; y += (fl & 32) ? d : -d; } else if (!(fl & 32)) { y += g.readInt16BE(p); p += 2; } ys[i] = y; }
    const out = []; let start = 0;
    for (let c = 0; c < nc; c++) { const end = endPts[c]; const pts = []; for (let i = start; i <= end; i++) pts.push({ x: xs[i], y: ys[i], on: !!(flags[i] & 1) }); out.push(pts); start = end + 1; }
    return out;
  }
  let off = 10; const res = [];
  for (; ;) {
    const flags = g.readUInt16BE(off), gi = g.readUInt16BE(off + 2); off += 4;
    let arg1, arg2;
    if (flags & 1) { arg1 = g.readInt16BE(off); arg2 = g.readInt16BE(off + 2); off += 4; } else { arg1 = g.readInt8(off); arg2 = g.readInt8(off + 1); off += 2; }
    let a = 1, b = 0, c2 = 0, d = 1;
    if (flags & 8) { const s = g.readInt16BE(off); off += 2; a = d = s / 16384; }
    else if (flags & 0x40) { const sx = g.readInt16BE(off) / 16384, sy = g.readInt16BE(off + 2) / 16384; off += 4; a = d = sx; }
    else if (flags & 0x80) { a = g.readInt16BE(off) / 16384; b = g.readInt16BE(off + 2) / 16384; c2 = g.readInt16BE(off + 4) / 16384; d = g.readInt16BE(off + 6) / 16384; off += 8; }
    const gx = (flags & 2) ? arg1 : arg1, gy = (flags & 2) ? arg2 : arg2;
    for (const cont of glyphContours(font, gi, depth + 1)) res.push(cont.map(pt => ({ x: a * pt.x + c2 * pt.y + gx, y: b * pt.x + d * pt.y + gy, on: pt.on })));
    if (!(flags & 0x20)) break;
  }
  return res;
}
function drawContours(ctx, contours, ox, oy, scale) {
  ctx.beginPath();
  for (const pts of contours) {
    if (pts.length < 2) continue;
    let startIdx = pts.findIndex(p => p.on); if (startIdx < 0) startIdx = 0;
    const P = i => pts[(i + pts.length) % pts.length];
    ctx.moveTo(ox + P(startIdx).x * scale, oy - P(startIdx).y * scale);
    let i = startIdx; const end = startIdx + pts.length;
    while (i < end) {
      const cur = P(i), next = P(i + 1);
      if (cur.on) {
        if (next.on) ctx.lineTo(ox + next.x * scale, oy - next.y * scale);
        else { const n2 = P(i + 2); ctx.quadraticCurveTo(ox + next.x * scale, oy - next.y * scale, ox + n2.x * scale, oy - n2.y * scale); i += 1; }
      } else {
        if (next.on) ctx.quadraticCurveTo(ox + cur.x * scale, oy - cur.y * scale, ox + next.x * scale, oy - next.y * scale);
        else { const mid = { x: (cur.x + next.x) / 2, y: (cur.y + next.y) / 2 }; ctx.quadraticCurveTo(ox + cur.x * scale, oy - cur.y * scale, ox + mid.x * scale, oy - mid.y * scale); }
      }
      i++;
    }
    ctx.closePath();
  }
  ctx.fill();
}

// ---- gather items ----
const file = process.argv[2];
const out = process.argv[3] || 'items.png';
const data = new Uint8Array(fs.readFileSync(file));
const doc = await pdfjs.getDocument({ data }).promise;
const page = await doc.getPage(1);
await page.getOperatorList();
const tc = await page.getTextContent();

// resolve font base names
const items = [];
for (const it of tc.items) {
  if (!it.str || !it.fontName) continue;
  let base = null;
  try { const f = await page.commonObjs.get(it.fontName); base = f.baseFont || null; } catch { }
  items.push({ str: it.str, font: it.fontName, base, x: it.transform[4], y: it.transform[5], w: it.width, h: it.height });
}
// group into rows by y
const rows = new Map();
for (const it of items) {
  const key = Math.round(it.y / 3);
  if (!rows.has(key)) rows.set(key, []);
  rows.get(key).push(it);
}
const sortedRows = [...rows.entries()].sort((a, b) => b[0] - a[0]);

const scale = 1.6;
const rowH = 44;
const canvas = createCanvas(1700, sortedRows.length * rowH + 20);
const ctx = canvas.getContext('2d');
ctx.fillStyle = '#fff'; ctx.fillRect(0, 0, canvas.width, canvas.height);

let rendered = 0;
for (let r = 0; r < sortedRows.length; r++) {
  const [, its] = sortedRows[r];
  its.sort((a, b) => b.x - a.x); // visual order: right to left => descending x
  let penX = 1660;
  const baseY = r * rowH + 34;
  for (const it of its) {
    const path = it.base && FONTFILES[it.base];
    if (!path) continue;
    const font = loadFont(path);
    // codepoints are GIDs (identity encoding)
    const cps = [...it.str];
    // paint order = as stored
    for (const ch of cps) {
      const gid = ch.codePointAt(0);
      if (gid < 1 || gid > 10000) continue;
      const cont = glyphContours(font, gid);
      if (!cont.length) continue;
      // measure advance
      let maxx = -1e9, minx = 1e9, maxy = -1e9, miny = 1e9;
      for (const c of cont) for (const p of c) { if (p.x > maxx) maxx = p.x; if (p.x < minx) minx = p.x; if (p.y > maxy) maxy = p.y; if (p.y < miny) miny = p.y; }
      const gs = scale * 0.9;
      // glyphs are painted left-to-right in stream order; advance by width
      const originX = penX - (maxx * gs);
      const originY = baseY;
      drawContours(ctx, cont, originX, originY, gs);
      penX -= (maxx - minx) * gs + 2;
    }
  }
  rendered++;
}
fs.writeFileSync(out, canvas.toBuffer('image/png'));
console.log('wrote', out, canvas.width + 'x' + canvas.height, 'rows=' + rendered);
await doc.destroy();

