const tc = await page.getTextContent();
const items = [];
for (const it of tc.items) {
  if (!it.str || !it.fontName) continue;
  let name = null;
  try { const f = await page.commonObjs.get(it.fontName); if (f && f.name) name = f.name; } catch { }
  items.push({ str: it.str, name, x: it.transform[4], y: it.transform[5] });
}
// group into rows
const sorted = items.slice().sort((a, b) => b.y - a.y);
const rows = [];
for (const it of sorted) {
  if (!rows.length || Math.abs(rows[rows.length - 1][0].y - it.y) > 8) rows.push([it]);
  else rows[rows.length - 1].push(it);
}
let sel = [];
for (const r of rows) {
  const hasUnknown = r.some(it => [...it.str].some(c => UNKNOWN.has(c.codePointAt(0))));
  if (filterUnknown && !hasUnknown) continue;
  sel.push(r);
}
console.log('rows selected', sel.length, 'of', rows.length);

const K = 0.05;      // font units -> px
const rowH = 95;
const W = 2400;
const canvas = createCanvas(W, sel.length * rowH + 30);
const ctx = canvas.getContext('2d');
ctx.fillStyle = '#fff'; ctx.fillRect(0, 0, canvas.width, canvas.height);
ctx.fillStyle = '#000';

for (let r = 0; r < sel.length; r++) {
  const rowItems = sel[r].slice().sort((a, b) => a.x - b.x);
  const baseY = r * rowH + 70;
  let penX = 20;
  for (const it of rowItems) {
    const path = it.name && FONTFILES[it.name];
    if (!path) continue;
    const font = loadFont(path);
    for (const ch of [...it.str]) {
      const gid = ch.codePointAt(0);
      if (gid < 1 || gid >= font.numGlyphs) continue;
      const cont = glyphContours(font, gid);
      if (cont.length) drawContours(ctx, cont, penX, baseY, K);
      penX += font.adv(gid) * K;
    }
    penX += 14;
  }
  ctx.fillStyle = '#cc0000'; ctx.font = '16px sans-serif'; ctx.textAlign = 'left';
  ctx.fillText(String(r), 2, baseY + 22);
  ctx.fillStyle = '#000';
}
fs.writeFileSync(out, canvas.toBuffer('image/png'));
console.log('wrote', out, canvas.width + 'x' + canvas.height);
await doc.destroy();

