import fs from 'fs';

const ttf = fs.readFileSync(process.argv[2]);
const n = ttf.readUInt16BE(4);
const T = {};
for (let i = 0; i < n; i++) { const o = 12 + i * 16; T[ttf.subarray(o, o + 4).toString('latin1')] = { off: ttf.readUInt32BE(o + 8), len: ttf.readUInt32BE(o + 12) }; }
if (!T.GSUB) { console.log('no GSUB'); process.exit(0); }
const G = T.GSUB.off;
const rd16 = o => ttf.readUInt16BE(G + o);
const rdS16 = o => ttf.readInt16BE(G + o);

const scriptList = rd16(4), featureList = rd16(6), lookupList = rd16(8);

// FeatureList -> featureTag + lookup indices (only for arab/dflt scripts we just take all)
const featCount = rd16(featureList);
const feats = [];
for (let i = 0; i < featCount; i++) {
  const o = featureList + 2 + i * 6;
  const tag = ttf.subarray(G + o, G + o + 4).toString('latin1');
  const off = rd16(o + 4);
  const lookupCount = rd16(featureList + off);
  const idx = [];
  for (let j = 0; j < lookupCount; j++) idx.push(rd16(featureList + off + 2 + j * 2));
  feats.push({ tag, idx });
}
console.log('features:', feats.map(f => f.tag + '[' + f.idx.join(',') + ']').join(' '));

const lookupCount = rd16(lookupList);
const lookups = [];
for (let i = 0; i < lookupCount; i++) lookups.push(rd16(lookupList + 2 + i * 2));

function coverageGlyphs(off) {
  const fmt = rd16(off);
  const out = [];
  if (fmt === 1) { const c = rd16(off + 2); for (let i = 0; i < c; i++) out.push(rd16(off + 4 + i * 2)); }
  else if (fmt === 2) { const c = rd16(off + 2); for (let i = 0; i < c; i++) { const s = rd16(off + 4 + i * 4), e = rd16(off + 6 + i * 4); for (let g = s; g <= e; g++) out.push(g); } }
  return out;
}

const single = new Map();   // orig -> sub (from all single subst)
const revSingle = new Map();// sub -> orig[]
const ligas = [];

for (let li = 0; li < lookupCount; li++) {
  const lo = lookupList + lookups[li];
  const type = rd16(lo), flags = rd16(lo + 2), subCount = rd16(lo + 4);
  for (let s = 0; s < subCount; s++) {
    const so = lo + rd16(lo + 6 + s * 2);
    const fmt = rd16(so);
    if (type === 1) {
      const cov = coverageGlyphs(so + rd16(so + 2));
      if (fmt === 1) {
        const delta = rdS16(so + 4);
        for (const g of cov) { const sub = (g + delta) & 0xFFFF; single.set(g, sub); if (!revSingle.has(sub)) revSingle.set(sub, []); revSingle.get(sub).push(g); }
      } else if (fmt === 2) {
        const c = rd16(so + 4);
        for (let i = 0; i < c; i++) { const g = cov[i]; const sub = rd16(so + 6 + i * 2); single.set(g, sub); if (!revSingle.has(sub)) revSingle.set(sub, []); revSingle.get(sub).push(g); }
      }
    } else if (type === 4 && fmt === 1) {
      const cov = coverageGlyphs(so + rd16(so + 2));
      const lc = rd16(so + 4);
      for (let i = 0; i < lc; i++) {
        const lo2 = so + rd16(so + 6 + i * 2);
        const first = rd16(lo2); const cc = rd16(lo2 + 2);
        const comps = []; for (let k = 0; k < cc - 1; k++) comps.push(rd16(lo2 + 4 + k * 2));
        const lig = rd16(lo2 + 4 + (cc - 1) * 2);
        ligas.push({ first, comps, lig, lookup: li });
      }
    }
  }
}
console.log('singleSubst entries:', single.size, 'ligatures:', ligas.length);

const targets = (process.argv[3] || '3941,3948,3950,3971,3981,3992').split(',').map(Number);
for (const t of targets) {
  const orig = revSingle.get(t);
  const produced = single.get(t);
  const inLiga = ligas.filter(l => l.lig === t || l.first === t || l.comps.includes(t));
  console.log(`GID ${t} (0x${t.toString(16)}): producedFrom=${orig ? orig.join(',') : '-'} produces=${produced !== undefined ? produced : '-'} inLiga=${inLiga.length ? JSON.stringify(inLiga.slice(0, 3)) : '-'}`);
}

// Also: list single substitutions where the result is one of the targets
console.log('\nAll single subst whose orig/sub involve targets:');
for (const [a, b] of single) if (targets.includes(a) || targets.includes(b)) console.log(`  ${a} -> ${b}`);

