/* فحص تشغيلي كامل عبر الـ API الحقيقي (يستخدم بيانات المستخدم الفعلية). */
import fs from 'node:fs';
import path from 'node:path';

const BASE = 'http://127.0.0.1:5199';
const PDF = process.argv[2] || 'C:\\Users\\cw\\Downloads\\تقرير قوائم الفصول (85).pdf';
const DATE = process.argv[3] || new Date().toISOString().slice(0, 10);

async function api(method, url, body) {
  const res = await fetch(BASE + url, {
    method,
    headers: body ? { 'content-type': 'application/json' } : undefined,
    body: body ? JSON.stringify(body) : undefined,
  });
  const json = await res.json().catch(() => ({}));
  return { status: res.status, json };
}

const out = [];
const say = (...a) => { out.push(a.join(' ')); console.log(...a); };

// 1) health
{
  const { json } = await api('GET', '/api/health');
  say('health:', json.ok, 'students=', json.stats?.students, 'classes=', json.stats?.classes);
}

// 2) extract
let extracted;
{
  const b64 = fs.readFileSync(PDF).toString('base64');
  const { status, json } = await api('POST', '/api/pdf/extract', { fileName: path.basename(PDF), data: b64 });
  say('extract:', status, 'rows=', json.rows?.length, 'review=', json.rows?.filter((r) => r.needsReview).length, 'unmapped=', json.unmapped?.length);
  say('header:', JSON.stringify(json.header));
  extracted = json;
  if (!json.rows?.length) throw new Error('لم يُستخرج أي طالب');
}

// 3) confirm (create class from header)
let classId;
{
  const { status, json } = await api('POST', '/api/pdf/confirm', {
    fileName: extracted.fileName,
    header: extracted.header,
    rows: extracted.rows.map((r) => ({ index: r.index, page: r.page, studentCode: r.studentCode, fullName: r.fullName })),
    mode: 'create_class',
  });
  say('confirm:', status, 'added=', json.added, 'updated=', json.updated, 'skipped=', json.skipped, 'needsReview=', json.needsReview, 'conflicts=', json.conflicts?.length);
  classId = json.classId;
  say('classId:', classId);
}

// 3b) re-import same file -> must not duplicate / delete anything
{
  const before = await api('GET', `/api/students?classId=${classId}&limit=500`);
  const { json } = await api('POST', '/api/pdf/confirm', {
    fileName: extracted.fileName,
    header: extracted.header,
    rows: extracted.rows.map((r) => ({ index: r.index, page: r.page, studentCode: r.studentCode, fullName: r.fullName })),
    classId,
    mode: 'merge',
  });
  const after = await api('GET', `/api/students?classId=${classId}&limit=500`);
  say('re-import: added=', json.added, 'updated=', json.updated, 'before=', before.json.total, 'after=', after.json.total);
}

// 4) search
{
  const q = encodeURIComponent('4727');
  const { json } = await api('GET', `/api/students?query=${q}&limit=5`);
  say('search "4727":', json.total, json.results?.map((r) => `${r.studentCode}:${r.fullName}`).join(' | '));
}

// 5) pick 3 verified students as absent
const list = await api('GET', `/api/students?classId=${classId}&limit=500`);
const verified = list.json.results.filter((s) => s.verificationStatus === 'verified');
const pick = verified.slice(0, 3).map((s) => s.id);
say('picked absent:', verified.slice(0, 3).map((s) => s.fullName).join('، '));
{
  const { status, json } = await api('POST', '/api/attendance/select', { date: DATE, classId, studentIds: pick });
  say('select:', status, 'count=', json.count);
}

// 6) day view
{
  const { json } = await api('GET', `/api/attendance/day?date=${DATE}`);
  say('day classes:', json.classes?.map((c) => `${c.classLabel}=${c.selectedCount}`).join(', '));
}

// 7) export
let exported;
{
  const { status, json } = await api('POST', '/api/attendance/export', { date: DATE, classId });
  say('export:', status, 'file=', json.fileName, 'rows=', json.rowCount, 'columns=', json.columns?.join(' | '), 'verified=', json.verified);
  exported = json;
  if (status !== 200) throw new Error('فشل التصدير: ' + json.error);
}

// 8) verify the produced workbook independently
{
  const ExcelJS = (await import('exceljs')).default;
  const wb = new ExcelJS.Workbook();
  await wb.xlsx.readFile(exported.path);
  const sheets = wb.worksheets.map((w) => w.name);
  const ws = wb.worksheets[0];
  const header = (ws.getRow(1).values || []).slice(1);
  const rows = [];
  ws.eachRow((r, n) => { if (n > 1) rows.push(r.values.slice(1)); });
  say('workbook sheets:', JSON.stringify(sheets));
  say('workbook header:', JSON.stringify(header));
  for (const r of rows) say('  row:', JSON.stringify(r), 'codeType=', typeof r[0]);
  say('workbook rows:', rows.length);
}

// 9) latest + download head
{
  const { json } = await api('GET', '/api/exports/latest');
  say('latest export:', json.ok, json.file?.path, json.file?.size, 'bytes');
  const res = await fetch(`${BASE}/api/exports/download?date=${DATE}&classId=${classId}`);
  say('download:', res.status, res.headers.get('content-type'));
}

// 10) automation with empty siteUrl -> honest missing_url
{
  const { json } = await api('POST', '/api/automation/run', { date: DATE, classId, export: false });
  say('automation:', json.status, '-', json.message);
}

// 11) logs
{
  const { json } = await api('GET', '/api/logs?limit=5');
  say('logs:', json.logs?.map((l) => `${l.level}: ${l.message}`).join(' || '));
}

fs.writeFileSync('_smoke.txt', out.join('\n'), 'utf8');
console.log('\nOK — الفحص التشغيلي الكامل نجح');

/**
 * استيراد كشف قوائم من ملف PDF من سطر الأوامر (بدون واجهة).
 * الاستخدام: node server/importRoster.mjs <file.pdf> [file2.pdf ...]
 *
 * ملاحظة: لا يُستبدل أي طالب تلقائياً عند اختلاف الاسم — يُسجَّل التعارض للمراجعة.
 */
import fs from 'node:fs';
import path from 'node:path';
import { extractPdf } from './pdfExtractor.mjs';
import {
  loadSchools, saveSchools, loadClasses, saveClasses, loadStudents, saveStudents,
  loadImportHistory, saveImportHistory, log, newId,
} from './store.mjs';

const normAr = (s) => String(s || '')
  .replace(/[أإآٱ]/g, 'ا').replace(/ة/g, 'ه').replace(/ى/g, 'ي')
  .replace(/[\u064B-\u0652\u0670\u0640]/g, '').replace(/\s+/g, ' ').trim();
const nowISO = () => new Date().toISOString();
const label = (c) => c.name || [c.grade, c.section].filter(Boolean).join(' / ');

async function importOne(file) {
  const name = path.basename(file);
  const bytes = fs.readFileSync(file);
  const result = await extractPdf(bytes, name);
  if (!result.rows.length) {
    console.log(`✗ ${name}: لم يُعثر على صفوف طلاب`);
    return null;
  }

  const schools = await loadSchools();
  let school = schools.items.find((s) => normAr(s.name) === normAr(result.header.school));
  if (!school) {
    school = {
      id: newId('sch'),
      name: result.header.school || '',
      directorate: result.header.directorate ? `مديري التربية والتعليم بال${result.header.directorate}` : '',
      administration: result.header.administration || '',
      active: true,
      createdAt: nowISO(),
      updatedAt: nowISO(),
    };
    schools.items.push(school);
    await saveSchools(schools);
  }

  const classes = await loadClasses();
  const key = `${school.id}|${normAr(result.header.className)}|${normAr(result.header.stage)}|${normAr(result.header.grade)}|${normAr(result.header.section)}`;
  let cls = classes.items.find((c) => c.syncKey === key);
  if (!cls) {
    cls = {
      id: newId('cls'),
      syncKey: key,
      schoolId: school.id,
      stage: result.header.stage || '',
      grade: result.header.grade || '',
      section: result.header.section || '',
      name: result.header.className || '',
      studentCount: 0,
      sourceFile: name,
      importedAt: nowISO(),
      createdAt: nowISO(),
      updatedAt: nowISO(),
    };
    classes.items.push(cls);
    await saveClasses(classes);
  }

  const students = await loadStudents();
  const now = nowISO();
  let added = 0;
  let updated = 0;
  let conflicts = 0;
  let needsReview = 0;

  for (const raw of result.rows) {
    const studentCode = String(raw.studentCode ?? '').trim();
    const fullName = String(raw.fullName ?? '').trim();
    const codeOk = /^\d{6,12}$/.test(studentCode);
    const nameOk = !!fullName && !fullName.includes('\uFFFD');
    if (!codeOk && !nameOk) continue;

    const reviewNotes = [];
    if (!codeOk) reviewNotes.push('كود الطالب غير مكتمل — عدّله قبل التصدير');
    if (!nameOk) reviewNotes.push('اسم الطالب غير مكتمل — عدّله قبل التصدير');
    const status = codeOk && nameOk ? 'verified' : 'needs_review';
    if (status === 'needs_review') needsReview += 1;

    const match = codeOk
      ? (s) => s.classId === cls.id && s.studentCode === studentCode
      : (s) => s.classId === cls.id && normAr(s.fullName) === normAr(fullName);
    const existing = students.items.find(match);

    if (existing) {
      if (nameOk && normAr(existing.fullName) !== normAr(fullName)) {
        conflicts += 1;
        console.log(`  ! تعارض للكود ${studentCode}: "${existing.fullName}" ≠ "${fullName}" (أُبقي القديم)`);
      } else {
        updated += 1;
      }
      existing.updatedAt = now;
      existing.lastSeenAt = now;
      if (existing.verificationStatus === 'verified' && status === 'needs_review') {
        existing.verificationStatus = 'needs_review';
        existing.reviewNotes = reviewNotes;
      }
      continue;
    }

    students.items.push({
      id: newId('stu'),
      studentCode,
      fullName,
      classId: cls.id,
      classLabel: label(cls),
      schoolId: school.id,
      stage: cls.stage,
      grade: cls.grade,
      section: cls.section,
      active: true,
      verificationStatus: status,
      reviewNotes,
      createdAt: now,
      updatedAt: now,
      source: { file: name, page: raw.page || 0, importedAt: now },
    });
    added += 1;
  }

  await saveStudents(students);
  cls.studentCount = students.items.filter((s) => s.classId === cls.id && s.active !== false).length;
  cls.importedAt = now;
  cls.sourceFile = name;
  await saveClasses(classes);

  const history = await loadImportHistory();
  history.items = [{
    id: newId('imp'),
    fileName: name,
    importedAt: now,
    classId: cls.id,
    classLabel: label(cls),
    added, updated, skipped: 0, needsReview,
    conflicts,
    conflictList: [],
    pages: result.pages,
    rows: result.rows.length,
    warnings: result.warnings,
  }, ...(history.items || [])].slice(0, 200);
  await saveImportHistory(history);
  await log('info', `استيراد CLI "${name}" إلى ${label(cls)}: أُضيف ${added}، حُدّث ${updated}، تعارض ${conflicts}، يحتاج مراجعة ${needsReview}`);

  console.log(`✓ ${name} → صنف "${label(cls)}" (${cls.id})`);
  console.log(`   أُضيف ${added} | حُدّث ${updated} | تعارض ${conflicts} | يحتاج مراجعة ${needsReview} | الكشف يقول ${result.header.totalStudents}`);
  for (const r of result.rows.filter((x) => x.needsReview)) {
    console.log(`   • مراجعة: [${r.studentCode || '—'}] ${r.fullName || '—'} — ${r.reviewNotes.join('؛ ')}`);
  }
  return cls;
}

const files = process.argv.slice(2);
if (!files.length) {
  console.error('الاستخدام: node server/importRoster.mjs <file.pdf> [file2.pdf ...]');
  process.exit(1);
}
for (const f of files) {
  try {
    await importOne(f);
  } catch (e) {
    console.log(`✗ ${f}: ${e.message}`);
  }
}

