import test from 'node:test';
import assert from 'node:assert/strict';
import { visualToLogical } from '../server/pdfExtractor.mjs';
import { makeSyntheticPdf } from './helpers.mjs';

test('تحويل الترتيب البصري إلى منطقي', () => {
  // سلسلة بصرية (تُرسم من اليسار إلى اليمين) تتحول إلى ترتيب منطقي عربي
  assert.equal(visualToLogical('د محم'), 'محمد');
  assert.equal(visualToLogical('ن ا م ث'), 'ثامن');
  // سلسلة لاتينية فقط: تُقرأ من اليمين إلى اليسار مثل ترتيب عرض PDF
  assert.equal(visualToLogical('olleh'), 'hello');
  // أرقام خالصة تبقى كما هي
  assert.equal(visualToLogical('472776652'), '472776652');
});

test('استخراج صفوف من ملف PDF اصطناعي (بيانات وهمية اصطناعية)', async () => {
  const { extractPdf } = await import('../server/pdfExtractor.mjs');

  const synthetic = [
    { code: '472776652', name: 'ALPHA ONE' },
    { code: '476267959', name: 'BETA TWO' },
    { code: '474638570', name: 'GAMMA THREE' },
    { code: null, name: 'DELTA FOUR' },       // صف بلا كود -> يجب أن يُعلَّم للمراجعة
    { code: '469103997', name: null },        // صف بلا اسم -> يجب أن يُعلَّم للمراجعة
  ];
  const bytes = await makeSyntheticPdf(synthetic);
  const result = await extractPdf(bytes, 'synthetic.pdf');

  assert.equal(result.ok, true);
  assert.equal(result.rows.length, 5, 'عدد الصفوف المستخرجة يجب أن يساوي عدد الصفوف المرسومة');

  const codes = result.rows.map((r) => r.studentCode);
  assert.equal(codes[0], '472776652');
  assert.equal(typeof codes[0], 'string', 'الكود يجب أن يبقى نصاً');
  assert.equal(codes[1], '476267959');
  assert.equal(codes[2], '474638570');
  assert.equal(codes[3], '', 'الصف بلا كود ينتج كوداً فارغاً');

  // الصفوف الناقصة يجب أن تُعلَّم بوضوح للمراجعة قبل التصدير
  assert.equal(result.rows[3].needsReview, true);
  assert.equal(result.rows[4].needsReview, true);
  assert.ok(result.rows[3].reviewNotes.length > 0, 'يجب تدوين سبب المراجعة');
  assert.ok(result.rows[4].reviewNotes.some((n) => n.includes('الاسم')), 'سبب المراجعة يجب أن يشير إلى الاسم');
});

test('استخراج PDF تالف/فارغ يُعيد نص خطأ واضحاً بدل الانهيار', async () => {
