/* تشخيص مؤقت: هل عناصر العرض الصفري مرتبطة برموز FFFD في أسماء الطلاب؟ */
import fs from 'node:fs';
import path from 'node:path';

const pdfjs = await import('pdfjs-dist/legacy/build/pdf.mjs');
const STANDARD_FONT_DIR = path.join(
  path.dirname(new URL(import.meta.url).pathname.replace(/^\//, '')),
  '..', 'node_modules', 'pdfjs-dist', 'standard_fonts',
);

const files = process.argv.slice(2);
for (const f of files) {
  const data = new Uint8Array(fs.readFileSync(f));
  const doc = await pdfjs.getDocument({
    data, useSystemFonts: false, isEvalSupported: false,
    standardFontDataUrl: `${STANDARD_FONT_DIR}${path.sep}`,
  }).promise;

  let zeroTotal = 0;
  let fffdTotal = 0;
  let rowsWithZero = 0;
  let rowsWithBoth = 0;
  let zeroNoFffd = 0;

  for (let p = 1; p <= doc.numPages; p++) {
    const page = await doc.getPage(p);
    const tc = await page.getTextContent();
    const items = tc.items
      .filter((it) => it.str && it.str.trim())
      .map((it) => ({ str: it.str, x: it.transform[4], y: it.transform[5], w: it.width || 0 }));

    // صفوف بحسب y (تباعد 8)
    const sorted = items.slice().sort((a, b) => b.y - a.y || a.x - b.x);
    const rows = [];
    for (const it of sorted) {
      const row = rows[rows.length - 1];
      if (row && Math.abs(it.y - row.refY) <= 8) { row.items.push(it); continue; }
      rows.push({ refY: it.y, items: [it] });
    }

    for (const row of rows) {
      const zero = row.items.filter((i) => i.w < 0.5);
      if (!zero.length) continue;
      rowsWithZero += 1;
      zeroTotal += zero.length;
      const hasFffd = row.items.some((i) => i.str.includes('�'));
      const fffdCount = row.items.reduce((n, i) => n + [...i.str].filter((c) => c === '�').length, 0);
      fffdTotal += fffdCount;
      if (hasFffd) rowsWithBoth += 1; else zeroNoFffd += 1;
      console.log(`p${p} y=${Math.round(row.refY)} zero=[${zero.map((z) => `${JSON.stringify(z.str)}`).join(',')}] fffd=${fffdCount} :: ${
        row.items.filter((i) => i.w >= 0.5).map((i) => i.str).join(' | ').slice(0, 120)}`);
    }
  }
  console.log(`\n${path.basename(f)}: rowsWithZero=${rowsWithZero} rowsWithZeroAndFffd=${rowsWithBoth} rowsWithZeroNoFffd=${zeroNoFffd} zeroItems=${zeroTotal} fffdChars=${fffdTotal}\n`);
}

