/* تشخيص: مقارنة الأسماء مع وبدون استبعاد عناصر العرض الصفري */
import fs from 'node:fs';
import path from 'node:path';

const { extractPdf } = await import('./pdfExtractor.mjs');

const files = process.argv.slice(2);
const before = {};
const after = {};

for (const f of files) {
  const b = fs.readFileSync(f);
  const name = path.basename(f);
  before[name] = await extractPdf(b, name);
  process.env.PDF_DROP_ZERO_WIDTH = '1';
  after[name] = await extractPdf(b, name);
  delete process.env.PDF_DROP_ZERO_WIDTH;
}

let changed = 0;
for (const name of Object.keys(before)) {
  const A = before[name].rows;
  const B = after[name].rows;
  console.log(`\n=== ${name} ===`);
  console.log(`rows: ${A.length} -> ${B.length}`);
  const mapB = new Map(B.map((r) => [r.studentCode || `#${r.index}`, r]));
  for (const a of A) {
    const b = mapB.get(a.studentCode || `#${a.index}`);
    if (!b) { console.log(`  ! اختفى صف: ${a.studentCode} ${a.fullName}`); changed++; continue; }
    if (a.fullName !== b.fullName) {
      changed++;
      console.log(`  ~ ${a.studentCode || '(لا كود)'}`);
      console.log(`      مع  : ${a.fullName}`);
      console.log(`      بدون: ${b.fullName}`);
    }
    if (a.needsReview !== b.needsReview) {
      console.log(`  ? مراجعة ${a.studentCode || '(لا كود)'}: ${a.needsReview} -> ${b.needsReview} ${b.reviewNotes.join('; ')}`);
    }
  }
  console.log(`needsReview: ${A.filter((r) => r.needsReview).length} -> ${B.filter((r) => r.needsReview).length}`);
  console.log(`unmapped: ${before[name].unmapped.length} -> ${after[name].unmapped.length}`);
}
console.log(`\nإجمالي الصفوف المتغيّرة: ${changed}`);

