53:   const at = (i) => (longLoca ? ttf.readUInt32BE(T.loca.off + i * 4) : ttf.readUInt16BE(T.loca.off + i * 2) * 2);
54:   const s = at(gid), e = at(gid + 1);
55:   if (!(e > s)) return null;
56:   return Buffer.from(ttf.subarray(T.glyf.off + s, T.glyf.off + e));
