/* يفحص صفوف «بلا كود»: هل هي صفوف حقيقية بلا كود، أم مشتتة من صفوف أخرى؟ */
import fs from 'node:fs';
import { extractPdf } from './pdfExtractor.mjs';

const files = process.argv.slice(2);
for (const f of files) {
  const res = await extractPdf(fs.readFileSync(f), f);
  const rows = res.rows;
  const coded = rows.filter((r) => r.studentCode);
  console.log(`\n=== ${f}`);
  console.log(`صفوف=${rows.length} بكود=${coded.length} بلا كود=${rows.length - coded.length} تكرار كود=${(res.duplicatesInFile || []).length}`);

  for (const r of rows.filter((x) => !x.studentCode)) {
    console.log(`\n  بلا كود [صف ${r.index} صفحة ${r.page}]: ${r.fullName}`);
    console.log(`    الخلايا: ${JSON.stringify(r.cells)}`);
    // هل اسمه جزء من اسم طالب مكود؟
