/* يعرض عناصر الصف الذي يحوي اسماً بلا كود، للتحقق البصري من المصدر */
import fs from 'node:fs';
import * as pdfjs from 'pdfjs-dist/legacy/build/pdf.mjs';

const [file, needle] = process.argv.slice(2);
const data = new Uint8Array(fs.readFileSync(file));
const doc = await pdfjs.getDocument({ data, useSystemFonts: true, cMapPacked: true, disableFontFace: false }).promise;

for (let p = 1; p <= doc.numPages; p++) {
  const page = await doc.getPage(p);
  const tc = await page.getTextContent();
  const items = tc.items.map((it) => ({ str: it.str, x: it.transform[4], y: it.transform[5], w: it.width }));
  const hit = items.find((it) => it.str.includes(needle));
  if (!hit) continue;
  const y = hit.y;
  console.log(`صفحة ${p} y=${y.toFixed(1)}\n--- عناصر نفس الصف (y ± 6) ---`);
  const row = items.filter((it) => Math.abs(it.y - y) < 6 && it.str.trim()).sort((a, b) => b.x - a.x);
  for (const it of row) {
    console.log(`  x=${it.x.toFixed(1).padStart(6)} .. ${(it.x + it.w).toFixed(1).padStart(6)}  w=${it.w.toFixed(1).padStart(6)}  ${JSON.stringify(it.str)}`);
  }
  console.log('\n--- صفوف مجاورة (y ± 22) ---');
  const near = items.filter((it) => Math.abs(it.y - y) < 22 && it.str.trim() && Math.abs(it.y - y) >= 6)
    .sort((a, b) => Math.abs(a.y - y) - Math.abs(b.y - y));
  for (const it of near.slice(0, 40)) {
    console.log(`  dy=${(it.y - y).toFixed(1).padStart(6)} x=${it.x.toFixed(1).padStart(6)}  ${JSON.stringify(it.str)}`);
  }
}

