/* يبحث عن صفوف فيها اسم في أقصى اليسار بلا رقم طالب مقابل */
import fs from 'node:fs';
import * as pdfjs from 'pdfjs-dist/legacy/build/pdf.mjs';

const file = process.argv[2];
const data = new Uint8Array(fs.readFileSync(file));
const doc = await pdfjs.getDocument({ data, useSystemFonts: true, cMapPacked: true }).promise;

const page = await doc.getPage(1);
const tc = await page.getTextContent();
const items = tc.items.map((it) => ({ str: it.str, x: it.transform[4], y: it.transform[5], w: it.width }))
  .filter((it) => it.str.trim());

// تجميع حسب y
const rows = new Map();
for (const it of items) {
  const key = Math.round(it.y);
  let found = null;
  for (const k of rows.keys()) if (Math.abs(k - key) <= 6) { found = k; break; }
  if (found === null) rows.set(key, [it]);
  else rows.get(found).push(it);
}

const ordered = [...rows.entries()].sort((a, b) => b[0] - a[0]);
for (const [y, its] of ordered) {
  const codes = its.filter((i) => /^\d{6,12}$/.test(i.str.replace(/\s+/g, '')));
  const nums = its.filter((i) => /^\d{1,2}$/.test(i.str.trim()));
  const farLeft = its.filter((i) => i.x < 160 && /\S/.test(i.str));
  if (codes.length >= 1 && codes.length <= 2 && farLeft.length && !codes.some((c) => c.x < 160)) {
    // اسم في اليسار بلا كود مقابل
    console.log(`y=${y} | أكواد=${codes.map((c) => c.str + '@' + c.x.toFixed(0)).join(',')} | أرقام صف=${nums.map((n) => n.str).join(',')} | يسار: ${farLeft.map((f) => 'x=' + f.x.toFixed(0) + ' w=' + f.w.toFixed(0)).join(' ; ')}`);
  }
}

/* يعرض كل صفوف الملف مع خلاياه ومواضعها، لمقارنتها بمسح الصفوف الخام */
import fs from 'node:fs';
import { extractPdf } from './pdfExtractor.mjs';

const file = process.argv[2];
const res = await extractPdf(fs.readFileSync(file), file);
for (const r of res.rows) {
  const cells = r.cells.map((c) => `${c.kind}[${c.x0.toFixed(0)}-${c.x1.toFixed(0)}]=${JSON.stringify(c.text.slice(0, 28))}`).join('  ');
  const flag = !r.studentCode ? '  <<< بلا كود' : '';
  console.log(`${String(r.index).padStart(2)} ${String(r.studentCode || '—').padStart(10)} ${cells}${flag}`);
}

