/* يفك ترميز عناصر صف بعينه ويطابقها بالمخرجات */
import fs from 'node:fs';
import * as pdfjs from 'pdfjs-dist/legacy/build/pdf.mjs';
import { visualToLogical } from './pdfExtractor.mjs';

const file = process.argv[2];
const data = new Uint8Array(fs.readFileSync(file));
const doc = await pdfjs.getDocument({ data, useSystemFonts: true, cMapPacked: true }).promise;

for (let p = 1; p <= doc.numPages; p++) {
  const page = await doc.getPage(p);
  const tc = await page.getTextContent();
  const items = tc.items.map((it) => ({ str: it.str, x: it.transform[4], y: it.transform[5], w: it.width }))
    .filter((it) => it.str.trim());

  const rows = new Map();
  for (const it of items) {
    const key = Math.round(it.y / 6) * 6;
    if (!rows.has(key)) rows.set(key, []);
    rows.get(key).push(it);
  }

  for (const [y, its] of [...rows.entries()].sort((a, b) => b[0] - a[0])) {
    const sorted = its.slice().sort((a, b) => b.x - a.x);
    const codes = sorted.filter((i) => /^\d{6,12}$/.test(i.str.replace(/\s+/g, '')));
    if (codes.length !== 2) continue;
    // صنف العناصر العربية غير المطابقة لأي كود
    const left = sorted.filter((i) => i.x < 180 && !/^\d+$/.test(i.str.trim()));
    if (left.length < 2) continue;
    // فجوة بين عنصرين متجاورين في اليسار
    const a = left[0], b = left[1];
    const gap = b.x - (a.x + a.w);
    if (gap <= 9) continue; // مدمجان أصلاً
    console.log(`\nصف y=${y} فجوة=${gap.toFixed(1)}`);
    for (const it of left) {
      const decoded = /[^\x00-\x7F]/.test(it.str) ? visualToLogical(it.str) : it.str;
      console.log(`  x=${it.x.toFixed(1)}..${(it.x + it.w).toFixed(1)} w=${it.w.toFixed(1)} بصري=${JSON.stringify(it.str)} منطقي=${JSON.stringify(decoded)}`);
    }
  }
}

