/* فحص نهائي لحالة قاعدة البيانات */
import fs from 'node:fs';

const read = (n) => JSON.parse(fs.readFileSync(`data/${n}.json`, 'utf8'));
const students = read('students').items || [];
const classes = read('classes').items || [];

const byClass = {};
for (const s of students) byClass[s.classLabel || '(بلا صنف)'] = (byClass[s.classLabel || '(بلا صنف)'] || 0) + 1;
const review = students.filter((s) => s.verificationStatus === 'needs_review');

console.log(`طلاب=${students.length} يحتاجون مراجعة=${review.length}`);
console.log(`حسب الصنف: ${Object.entries(byClass).map(([k, v]) => `${k}=${v}`).join('  ')}`);
console.log(`الأصناف: ${classes.map((c) => `${c.label}=${c.studentCount}`).join('  ')}`);
console.log(`بيانات ناقصة: ${students.filter((s) => !s.classLabel || !s.schoolId || s.active === undefined).length}`);
console.log(`أسماء تالفة: ${students.filter((s) => /[0-9]/.test(s.fullName) || s.fullName.includes('\uFFFD')).length}`);
console.log(`بلا كود: ${students.filter((s) => !s.studentCode).length}`);
console.log(`\nالسجلات التي تحتاج تدخلاً يدوياً:`);
for (const s of review) {
  console.log(`  [${s.studentCode || '—'}] ${s.fullName}`);
  for (const n of s.reviewNotes || []) console.log(`        • ${n}`);
}

