 * تحديد غائبين → تصدير Excel → إعادة قراءة الملف والتحقق من المواصفات → تنظيف.
 * يستخدم صنف 1 / 4 (لا يحتوي أي سجل مراجعة) وتاريخاً تجريبياً بعيداً.
 */
import fs from 'node:fs';
import path from 'node:path';
import ExcelJS from 'exceljs';

const B = 'http://127.0.0.1:5199';
const DATE = '2026-10-30';
const api = async (p, opt) => {
  const r = await fetch(B + p, opt);
  const j = await r.json().catch(() => ({}));
  return { status: r.status, body: j };
};

const meta = await api('/api/meta');
const cls = meta.body.classes.find((c) => c.label === '1 / 4');
if (!cls) throw new Error('لم أجد صنف 1 / 4');

const rep = await api(`/api/attendance/report?date=${DATE}&classId=${cls.id}`);
const students = rep.body.students;
console.log(`صنف ${cls.label}: ${students.length} طالباً | مراجعة: ${students.filter((s) => s.verificationStatus === 'needs_review').length}`);

// اختر أول طالبين سليمين
const pick = students.filter((s) => !/^\d{6,12}$/.test(String(s.studentCode || '')) === false).slice(0, 2);
if (pick.length < 2) throw new Error('لم أجد طالبين بكود سليم');
console.log(`المختارون: ${pick.map((s) => s.studentCode + ' — ' + s.fullName).join(' | ')}`);

const sel = await api('/api/attendance/select', {
  method: 'POST', headers: { 'content-type': 'application/json' },
  body: JSON.stringify({ date: DATE, classId: cls.id, studentIds: pick.map((s) => s.id) }),
});
console.log('select:', sel.status, JSON.stringify(sel.body));

const exp = await api('/api/attendance/export', {
  method: 'POST', headers: { 'content-type': 'application/json' },
  body: JSON.stringify({ date: DATE, classId: cls.id }),
});
console.log('export:', exp.status, JSON.stringify(exp.body).slice(0, 400));

if (exp.status === 200 && exp.body.fileName) {
  const filePath = path.join('exports', exp.body.fileName);
  const wb = new ExcelJS.Workbook();
  await wb.xlsx.readFile(filePath);
  const ws = wb.worksheets[0];
  const header = [];
  ws.getRow(1).eachCell((c, n) => (header[n] = String(c.value ?? '')));
  console.log('الأوراق:', wb.worksheets.length);
  console.log('العناوين:', header.filter(Boolean).join(' | '));
  for (let r = 2; r <= ws.rowCount; r++) {
    const row = ws.getRow(r);
    const vals = [];
    row.eachCell({ includeEmpty: true }, (c, n) => vals[n] = c.value);
    console.log(`  صف ${r}: كود=${JSON.stringify(vals[1])} (${typeof vals[1]}) صف=${vals[2]} اسم=${vals[3]} فصل=${vals[4]} أيام=${vals[5]}`);
  }

  // تنظيف: احذف ملف التصدير وسجل الحضور التجريبي
  fs.unlinkSync(filePath);
  console.log('حُذف ملف التصدير التجريبي');
}

// إزالة سجل الحضور التجريبي
await api('/api/attendance/select', {
  method: 'POST', headers: { 'content-type': 'application/json' },
  body: JSON.stringify({ date: DATE, classId: cls.id, studentIds: [] }),
});
console.log('أُفرغ سجل الحضور التجريبي');

