      'تم رصد اختبار روبوت بعد محاولة الحفظ. لا يمكن تجاوزه آلياً — أكمل يدوياً، المتصفح مفتوح.',
      { manualHandoff: true, siteMessage });
  }
  return finish('blocked_captcha', 'تم رصد اختبار روبوت بعد محاولة الحفظ.', { siteMessage });
}

