/**
 * اختبار حقيقي لمنطق الحفظ في الأتمتة على صفحة تحاكي موقع المديرية:
 *   <button id="saveButton" ...>حفظ بيانات الغياب</button>
 *   <div id="message" class="message error">كود الطالب مطلوب في الصف رقم 1.</div>
 * يتحقق من: النقر على #saveButton، وقراءة نص #message وعرضه كما هو.
 */
import http from 'node:http';
import { runAutomation } from './automation.mjs';

const page = (mode) => `<!doctype html>
<html dir="rtl" lang="ar"><head><meta charset="utf-8"><title>محاكاة موقع المديرية</title></head>
<body>
  <h1>رفع بيانات الغياب</h1>
  <p>صفحة اختبار محلية فقط — لا اتصال بأي موقع حقيقي.</p>
  <input type="file" id="f" />
  <button id="saveButton" class="green" onclick="saveAbsence()">حفظ بيانات الغياب</button>
  <div id="message" class="message"></div>
  <script>
    function saveAbsence() {
      var m = document.getElementById('message');
      if ('${mode}' === 'error') {
        m.className = 'message error';
        m.textContent = 'كود الطالب مطلوب في الصف رقم 1.';
      } else {
        m.className = 'message success';
        m.textContent = 'تم الحفظ بنجاح — 3 طلاب.';
      }
    }
  </script>
</body></html>`;

const server = http.createServer((req, res) => {
  const mode = req.url.includes('success') ? 'success' : 'error';
  res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
  res.end(page(mode));
});

await new Promise((r) => server.listen(5299, '127.0.0.1', r));
console.log('خادم المحاكاة يعمل على 5299\n');

const base = {
  browser: 'msedge',
  headless: true,
  manualFallback: false,
  timeoutMs: 20000,
  successIndicators: ['تم الحفظ بنجاح'],
};

for (const mode of ['error', 'success']) {
  const res = await runAutomation({
    date: '2026-11-03',
    classId: 'cls_test',
    excelPath: null,
    settings: { ...base, siteUrl: `http://127.0.0.1:5299/${mode}` },
  });
  console.log(`=== الحالة: ${mode} ===`);
  console.log(`  status   : ${res.status}`);
  console.log(`  ok       : ${res.ok}`);
  console.log(`  message  : ${res.message}`);
  console.log(`  siteText : ${JSON.stringify(res.siteMessage && res.siteMessage.text)}`);
  console.log(`  steps    :`);
  for (const s of res.steps) console.log(`     ${s.ok ? '✓' : '✗'} ${s.step} — ${s.detail}`);
  console.log('');
}

server.close();

/**
 * اختبار نقطة تصفير البيانات على نسخة معزولة (APP_DATA_DIR مؤقت) —
 * لا يلمس بيانات المستخدم الحقيقية إطلاقاً.
 */
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { spawn } from 'node:child_process';

const tmp = path.join(os.tmpdir(), `ghiyab-reset-test-${Date.now()}`);
fs.mkdirSync(path.join(tmp, 'data'), { recursive: true });
fs.mkdirSync(path.join(tmp, 'exports'), { recursive: true });
for (const f of ['students.json', 'classes.json', 'attendance.json', 'import_history.json', 'settings.json', 'schools.json', 'glyph_overrides.json', 'logs.json']) {
  const src = path.join('data', f);
  if (fs.existsSync(src)) fs.copyFileSync(src, path.join(tmp, 'data', f));
}

const PORT = 5298;
const srv = spawn(process.execPath, ['server/index.mjs'], {
  env: { ...process.env, APP_DATA_DIR: path.join(tmp, 'data'), APP_EXPORT_DIR: path.join(tmp, 'exports'), PORT: String(PORT) },
  stdio: 'ignore',
});

const B = `http://127.0.0.1:${PORT}`;
const wait = (ms) => new Promise((r) => setTimeout(r, ms));

// انتظر الإقلاع
for (let i = 0; i < 60; i++) {
  try { await fetch(B + '/api/health'); break; } catch { await wait(250); }
}

const before = await (await fetch(B + '/api/health')).json();
console.log('قبل: طلاب=' + before.stats.students + ' أصناف=' + before.stats.classes + ' استيرادات=' + before.stats.imports);

// 1) تأكيد ناقص → يجب أن يُرفض
const badRes = await fetch(B + '/api/admin/reset', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({}) });
console.log('تأكيد ناقص →', badRes.status, (await badRes.json()).error);

// 2) تصفير فعلي
const okRes = await fetch(B + '/api/admin/reset', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ confirm: 'RESET' }) });
const okBody = await okRes.json();
console.log('تصفير →', okRes.status, JSON.stringify(okBody));

const after = await (await fetch(B + '/api/health')).json();
console.log('بعد: طلاب=' + after.stats.students + ' أصناف=' + after.stats.classes + ' استيرادات=' + after.stats.imports);

const settings = await (await fetch(B + '/api/settings')).json();
const meta = await (await fetch(B + '/api/meta')).json();
console.log('الإعدادات محفوظة: siteUrl=' + JSON.stringify(settings.settings.siteUrl) + ' | المدرسة: ' + (meta.schools[0] ? meta.schools[0].name : 'مفقودة'));

const backups = fs.readdirSync(path.join(tmp, 'data', 'backups'));
console.log('نسخ احتياطية: ' + backups.length + ' ملف');
console.log('منها students: ' + backups.filter((b) => b.startsWith('students.')).length);

const ok = after.stats.students === 0 && after.stats.classes === 0 && after.stats.imports === 0
  && badRes.status === 400 && okRes.status === 200 && backups.length > 0;

console.log(ok ? '\n✅ نجح الاختبار' : '\n❌ فشل الاختبار');
srv.kill();
fs.rmSync(tmp, { recursive: true, force: true });
process.exit(ok ? 0 : 1);

