    info = await el.evaluate((n) => ({
      text: String(n.innerText || n.textContent || '').trim(),
      cls: String(n.className || ''),
      visible: !!(n.offsetWidth || n.offsetHeight || n.getClientRects().length),
    })).catch(() => ({ text: '', cls: '', visible: false }));
