import http from 'node:http';

const page = (mode) => `<!doctype html>
<html dir="rtl" lang="ar"><head><meta charset="utf-8"><title>محاكاة</title></head>
<body>
  <h1>رفع بيانات الغياب</h1>
  <input type="file" id="f" />
  <button id="saveButton" class="green" onclick="saveAbsence()">حفظ بيانات الغياب</button>
  <div id="message" class="message"></div>
  <script>
    function saveAbsence() {
      var m = document.getElementById('message');
      if ('${mode}' === 'error') {
        m.className = 'message error';
        m.textContent = 'كود الطالب مطلوب في الصف رقم 1.';
      } else {
        m.className = 'message success';
        m.textContent = 'تم الحفظ بنجاح';
      }
    }
  </script>
</body></html>`;

http.createServer((req, res) => {
  const mode = req.url.includes('success') ? 'success' : 'error';
  res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
  res.end(page(mode));
}).listen(5297, '127.0.0.1', () => console.log('mock on 5297'));

